#include <stdio.h>

int main(void)
{
    float a, b;
    char op;

    printf("Enter expression (e.g. 12 * 5): ");
    scanf("%f %c %f", &a, &op, &b);

    switch (op)
    {
        case '+': printf("Result = %.2f\n", a + b); break;
        case '-': printf("Result = %.2f\n", a - b); break;
        case '*': printf("Result = %.2f\n", a * b); break;
        case '/':
            if (b != 0)
                printf("Result = %.2f\n", a / b);
            else
                printf("Error: division by zero\n");
            break;
        default:  printf("Invalid operator\n");
    }
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    char ch;

    printf("Enter an alphabet: ");
    scanf(" %c", &ch);

    if (!isalpha(ch)) {
        printf("Not an alphabet\n");
        return 0;
    }

    switch (tolower(ch))
    {
        case 'a':
        case 'e':
        case 'i':
        case 'o':
        // fall-through groups the vowels
        case 'u':
            printf("%c is a VOWEL\n", ch);
            break;
        default:
            printf("%c is a CONSONANT\n", ch);
    }
    return 0;
}

