#include <stdio.h>

int main(void)
{
    int n, temp, d, rev = 0;

    printf("Enter a number: ");
    scanf("%d", &n);

    // keep original value
    temp = n;
    while (temp > 0)
    {
        // last digit
        d = temp % 10;
        // append digit to rev
        rev = rev * 10 + d;
        // remove last digit
        temp = temp / 10;
    }

    printf("Reverse = %d\n", rev);
    if (rev == n)
        printf("%d is a PALINDROME\n", n);
    else
        printf("%d is NOT a palindrome\n", n);
    return 0;
}

