}

#include <stdio.h>

int main(void)
{
    int n, i, isPrime = 1;

    printf("Enter a number: ");
    scanf("%d", &n);

    if (n < 2)
        isPrime = 0;

    for (i = 2; i * i <= n; i++)
    {
        if (n % i == 0)
        {
            // divisor found
            isPrime = 0;
            // no need to check further
            break;
        }
    }

    if (isPrime)
        printf("%d is a PRIME number\n", n);
    else
        printf("%d is NOT a prime number\n", n);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, temp, d, digits = 0, i, p;
    long sum = 0;

    printf("Enter a number: ");
    scanf("%d", &n);

    // count digits
    for (temp = n; temp > 0; temp /= 10)
        digits++;

    temp = n;
    while (temp > 0)
    {
        d = temp % 10;
        p = 1;
        // p = d ^ digits
        for (i = 1; i <= digits; i++)
            p = p * d;
        sum = sum + p;
        temp = temp / 10;
    }

    if (sum == n)
        printf("%d is an ARMSTRONG number\n", n);
    else
        printf("%d is NOT an Armstrong number\n", n);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 4, i, j;

    /* Pattern 1: right triangle of stars */
    for (i = 1; i <= n; i++)
    {
        for (j = 1; j <= i; j++)
            printf("* ");
        printf("\n");
    }
    printf("\n");

    /* Pattern 2: number pyramid */
    for (i = 1; i <= n; i++)
    {
        // leading spaces
        for (j = 1; j <= n - i; j++)
            printf(" ");
        for (j = 1; j <= i; j++)
            printf("%d ", j);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int i, n, sum = 0;

    printf("Enter up to 10 numbers (0 to stop):\n");
    for (i = 1; i <= 10; i++)
    {
        scanf("%d", &n);
        if (n == 0)
            // leave the loop
            break;
        if (n < 0)
            // skip negative, go to i++
            continue;
        sum = sum + n;
    }
    printf("Sum of positive numbers = %d\n", sum);
    return 0;
}

